// ***************
// Filename: edge_event_capture_top.sv
// Author: FPGA Cores 4 U
// Description: edge_event_capture with its AXI4-Lite register interface, the
//   block designs and testbenches instantiate: the register map
//   edge_event_capture_regs (u_regs, src/include/edge_event_capture_regs.sv,
//   ID "EDGE", VERSION and DATE at 0x00-0x08, the registers from 0x10) and
//   the logic edge_event_capture (u_core, src/edge_event_capture.sv), joined
//   by their register ports (cfg_* to the logic, sts_* back). Generated by
//   ip/scripts/regmap_gen.py from edge_event_capture_regs.json and the ports
//   of edge_event_capture: regenerate after changing either. Clock - aclk.
//   Reset - synchronous active low aresetn.
// Date: 2026-10-12
module edge_event_capture_top #(
  parameter int WIDTH = 8,
  parameter int SYNC_STAGES = 2,
  parameter int FIFO_DEPTH = 512,
  parameter int TS_W = 32
) (
  input  logic                    aclk,
  input  logic                    aresetn,
  input  logic [7:0]              s_axil_awaddr,
  input  logic                    s_axil_awvalid,
  output logic                    s_axil_awready,
  input  logic [31:0]             s_axil_wdata,
  input  logic [3:0]              s_axil_wstrb,
  input  logic                    s_axil_wvalid,
  output logic                    s_axil_wready,
  output logic [1:0]              s_axil_bresp,
  output logic                    s_axil_bvalid,
  input  logic                    s_axil_bready,
  input  logic [7:0]              s_axil_araddr,
  input  logic                    s_axil_arvalid,
  output logic                    s_axil_arready,
  output logic [31:0]             s_axil_rdata,
  output logic [1:0]              s_axil_rresp,
  output logic                    s_axil_rvalid,
  input  logic                    s_axil_rready,
  input  logic [WIDTH-1:0]        sig_i,
  output logic [WIDTH-1:0]        rise_o,
  output logic [WIDTH-1:0]        fall_o,
  output logic                    irq_o,
  output logic [TS_W+2*WIDTH-1:0] m_axis_tdata,
  output logic                    m_axis_tvalid,
  input  logic                    m_axis_tready,
  output logic                    m_axis_tlast
);
  // register ports between the register map and the logic
  logic cfg_ctrl;
  logic [WIDTH-1:0] cfg_rise_en;
  logic [WIDTH-1:0] cfg_fall_en;
  logic [15:0] cfg_debounce;
  logic [WIDTH-1:0] cfg_rise_pend;
  logic [WIDTH-1:0] sts_rise_pend_set;
  logic [WIDTH-1:0] cfg_fall_pend;
  logic [WIDTH-1:0] sts_fall_pend_set;
  logic [31:0] sts_event_count;
  logic [31:0] sts_timestamp;
  logic [31:0] sts_drop_count;
  logic [WIDTH-1:0] cfg_irq_en;

  edge_event_capture_regs #(
    .WIDTH(WIDTH)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(),
    .rise_en_o(cfg_rise_en),
    .rise_en_wr_o(),
    .fall_en_o(cfg_fall_en),
    .fall_en_wr_o(),
    .debounce_o(cfg_debounce),
    .debounce_wr_o(),
    .rise_pend_o(cfg_rise_pend),
    .rise_pend_wr_o(),
    .rise_pend_set_i(sts_rise_pend_set),
    .fall_pend_o(cfg_fall_pend),
    .fall_pend_wr_o(),
    .fall_pend_set_i(sts_fall_pend_set),
    .event_count_i(sts_event_count),
    .timestamp_i(sts_timestamp),
    .drop_count_i(sts_drop_count),
    .irq_en_o(cfg_irq_en),
    .irq_en_wr_o()
  );
  edge_event_capture #(
    .WIDTH(WIDTH),
    .SYNC_STAGES(SYNC_STAGES),
    .FIFO_DEPTH(FIFO_DEPTH),
    .TS_W(TS_W)
  ) u_core (
    .aclk,
    .aresetn,
    .sig_i,
    .rise_o,
    .fall_o,
    .irq_o,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .cfg_ctrl,
    .cfg_rise_en,
    .cfg_fall_en,
    .cfg_debounce,
    .cfg_rise_pend,
    .sts_rise_pend_set,
    .cfg_fall_pend,
    .sts_fall_pend_set,
    .sts_event_count,
    .sts_timestamp,
    .sts_drop_count,
    .cfg_irq_en
  );
endmodule
